class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        INF = 10 ** 9

        def ok(limit: int) -> bool:
            dp = [[INF] * (limit + 1) for _ in range(2)]
            first = 1 if s[0] == '1' else 0
            for b in (0, 1):
                dp[b][1] = 1 if b != first else 0

            for i in range(1, n):
                ndp = [[INF] * (limit + 1) for _ in range(2)]
                cur = 1 if s[i] == '1' else 0

                for b in (0, 1):
                    for run in range(1, limit + 1):
                        cost = dp[b][run]
                        if cost >= INF:
                            continue

                        for nb in (0, 1):
                            new_run = run + 1 if nb == b else 1
                            if new_run > limit:
                                continue

                            new_cost = cost + (1 if nb != cur else 0)
                            if new_cost < ndp[nb][new_run]:
                                ndp[nb][new_run] = new_cost

                dp = ndp

            best = INF
            for b in (0, 1):
                for run in range(1, limit + 1):
                    if dp[b][run] < best:
                        best = dp[b][run]

            return best <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo
```

