class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        n = len(coins)
        subsets = []

        for mask in range(1, 1 << n):
            l = 1
            bits = 0
            for i in range(n):
                if mask & (1 << i):
                    bits += 1
                    l = l // gcd(l, coins[i]) * coins[i]
            sign = 1 if bits % 2 == 1 else -1
            subsets.append((l, sign))

        def count_leq(x: int) -> int:
            total = 0
            for l, sign in subsets:
                if l <= x:
                    total += sign * (x // l)
            return total

        lo, hi = 0, min(coins) * k

        while lo < hi:
            mid = (lo + hi) // 2
            if count_leq(mid) >= k:
                hi = mid
            else:
                lo = mid + 1

        return lo
