from typing import List
from collections import deque
from functools import lru_cache

class Solution:
    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        n = len(positions)
        moves = [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]

        @lru_cache(None)
        def dist(x1: int, y1: int, x2: int, y2: int) -> int:
            if x1 == x2 and y1 == y2:
                return 0
            q = deque([(x1, y1)])
            d = [[-1] * 50 for _ in range(50)]
            d[x1][y1] = 0
            while q:
                x, y = q.popleft()
                if x == x2 and y == y2:
                    return d[x][y]
                for dx, dy in moves:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < 50 and 0 <= ny < 50 and d[nx][ny] == -1:
                        d[nx][ny] = d[x][y] + 1
                        q.append((nx, ny))
            return -1

        full_mask = (1 << n) - 1
        memo = {}

        def dfs(pos, mask: int) -> int:
            if mask == 0:
                return 0

            key = (pos, mask)
            if key in memo:
                return memo[key]

            captured = n - bin(mask).count("1")
            alice_turn = captured % 2 == 0

            best = None
            m = mask
            while m:
                lsb = m & -m
                i = lsb.bit_length() - 1
                m ^= lsb

                target = positions[i]
                cost = dist(pos[0], pos[1], target[0], target[1])
                new_mask = mask ^ (1 << i)
                val = cost + dfs((target[0], target[1]), new_mask)

                if alice_turn:
                    if best is None or val > best:
                        best = val
                else:
                    if best is None or val < best:
                        best = val

            memo[key] = best
            return best

        return dfs((kx, ky), full_mask)
```

