from collections import Counter

class Solution:
    def countPairs(self, coordinates: List[List[int]], k: int) -> int:
        freq = Counter()
        for x, y in coordinates:
            freq[(x, y)] += 1

        if k == 0:
            ans = 0
            for cnt in freq.values():
                ans += cnt * (cnt - 1) // 2
            return ans

        ans = 0
        for (x, y), cnt in freq.items():
            for a in range(k + 1):
                b = k - a
                x2 = x ^ a
                y2 = y ^ b
                other = (x2, y2)
                if other in freq:
                    ans += cnt * freq[other]

        return ans // 2
