from typing import List

class Solution:
    def maximumSumSubsequence(self, nums: List[int], queries: List[List[int]]) -> int:
        MOD = 10**9 + 7
        NEG = -10**18

        def mul(A, B):
            a00, a01, a10, a11 = A
            b00, b01, b10, b11 = B
            return (
                max(a00 + b00, a01 + b10),
                max(a00 + b01, a01 + b11),
                max(a10 + b00, a11 + b10),
                max(a10 + b01, a11 + b11),
            )

        ID = (0, NEG, NEG, 0)

        def make(x):
            return (0, 0, x, NEG)

        n = len(nums)
        size = 1
        while size < n:
            size <<= 1

        tree = [ID] * (2 * size)

        for i, v in enumerate(nums):
            tree[size + i] = make(v)

        for i in range(size - 1, 0, -1):
            tree[i] = mul(tree[i * 2 + 1], tree[i * 2])

        total = 0

        for pos, x in queries:
            idx = size + pos
            tree[idx] = make(x)
            idx >>= 1

            while idx:
                tree[idx] = mul(tree[idx * 2 + 1], tree[idx * 2])
                idx >>= 1

            m = tree[1]
            ans = max(m[0], m[2])
            total = (total + ans) % MOD

        return total
