class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        max_n = max(zero, one, limit) + 5
        C = [[0] * (max_n + 1) for _ in range(max_n + 1)]
        for i in range(max_n + 1):
            C[i][0] = 1
            C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        def comb(n: int, k: int) -> int:
            if n < 0 or k < 0 or k > n:
                return 0
            return C[n][k]

        def ways(n: int, k: int, L: int) -> int:
            if k <= 0:
                return 0
            if n < k or n > k * L:
                return 0

            res = 0
            for i in range((n - k) // L + 1):
                term = comb(k, i) * comb(n - i * L - 1, k - 1) % MOD
                if i % 2 == 0:
                    res += term
                else:
                    res -= term
            return res % MOD

        ans = 0

        equal_sum = 0
        for k in range(1, min(zero, one) + 1):
            equal_sum = (equal_sum + ways(zero, k, limit) * ways(one, k, limit)) % MOD
        ans = (ans + 2 * equal_sum) % MOD

        for k in range(1, min(one, zero - 1) + 1):
            ans = (ans + ways(zero, k + 1, limit) * ways(one, k, limit)) % MOD

        for k in range(1, min(zero, one - 1) + 1):
            ans = (ans + ways(one, k + 1, limit) * ways(zero, k, limit)) % MOD

        return ans % MOD
