from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        size = 1
        while size < n:
            size <<= 1

        tree = [-1] * (2 * size)
        for i in range(n):
            tree[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[i << 1], tree[(i << 1) | 1])

        def update(idx: int, val: int) -> None:
            p = idx + size
            tree[p] = val
            p >>= 1
            while p:
                tree[p] = max(tree[p << 1], tree[(p << 1) | 1])
                p >>= 1

        def find_first(x: int) -> int:
            if tree[1] < x:
                return -1
            idx = 1
            while idx < size:
                if tree[idx << 1] >= x:
                    idx = idx << 1
                else:
                    idx = (idx << 1) | 1
            pos = idx - size
            return pos if pos < n else -1

        unplaced = 0
        for f in fruits:
            idx = find_first(f)
            if idx == -1:
                unplaced += 1
            else:
                update(idx, -1)

        return unplaced
