from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_upto(n: int) -> int:
            if n <= 0:
                return 0

            digits = str(n)

            @lru_cache(None)
            def dfs(pos: int, tight: bool, started: bool, prod: int, digit_sum: int) -> int:
                if pos == len(digits):
                    if not started:
                        return 0
                    return 1 if prod % digit_sum == 0 else 0

                limit = int(digits[pos]) if tight else 9
                total = 0

                for d in range(limit + 1):
                    next_tight = tight and (d == int(digits[pos]))

                    if not started and d == 0:
                        total += dfs(pos + 1, next_tight, False, 1, 0)
                    else:
                        total += dfs(pos + 1, next_tight, True, prod * d, digit_sum + d)

                return total

            return dfs(0, True, False, 1, 0)

        return count_upto(r) - count_upto(l - 1)
