class Solution:
    def punishmentNumber(self, n: int) -> int:
        ans = 0

        for i in range(1, n + 1):
            s = str(i * i)
            length = len(s)
            found = False

            for mask in range(1 << (length - 1)):
                total = 0
                start = 0

                for j in range(length - 1):
                    if mask & (1 << j):
                        total += int(s[start:j + 1])
                        start = j + 1

                total += int(s[start:])

                if total == i:
                    found = True
                    break

            if found:
                ans += i * i

        return ans
